export const RECIPE_CHECKOUT_FULFILLMENT = "```ts\n// db/schema.ts\nimport { schema, table, id, text, integer, boolean, timestamp, serverOnly } from 'somewhere/db';\n\nexport default schema({\n  payment_requests: table({\n    id: id({ uuid: true }),\n    checkout_session_id: text({ unique: true }),\n    amount_cents: integer(),\n    currency: text(),\n    livemode: boolean(),\n    stripe_account_id: text({ nullable: true }),\n    status: text({ default: 'pending' }),\n    paid_event_id: text({ nullable: true }),\n    paid_at: timestamp({ nullable: true }),\n  }, { scope: serverOnly() }),\n});\n```\n\n```ts\n// api/payments/stripe.ts\nimport Stripe from 'stripe';\n\nexport default async function (req, sw) {\n  if (req.method !== 'POST') return new Response('method not allowed', { status: 405 });\n  const raw = await req.text();\n  const stripe = new Stripe(sw.env.STRIPE_SECRET_KEY);\n  let event;\n  try {\n    event = await stripe.webhooks.constructEventAsync(\n      raw, req.headers.get('stripe-signature') ?? '', sw.env.STRIPE_WEBHOOK_SECRET,\n    );\n  } catch {\n    return new Response('bad signature', { status: 400 });\n  }\n  if (event.type !== 'checkout.session.completed') return new Response('ok');\n  const session = event.data.object;\n  if (session.mode !== 'payment' || session.payment_status !== 'paid' ||\n      typeof session.id !== 'string' || !Number.isSafeInteger(session.amount_total) ||\n      typeof session.currency !== 'string' || typeof session.livemode !== 'boolean' ||\n      event.livemode !== session.livemode) return new Response('payment mismatch', { status: 409 });\n  const found = await sw.db.from('payment_requests', { where: { checkout_session_id: session.id }, limit: 1 });\n  const order = found.data[0];\n  if (typeof event.id !== 'string' || (event.account !== undefined && typeof event.account !== 'string')) {\n    return new Response('payment mismatch', { status: 409 });\n  }\n  const account = event.account ?? null;\n  if (!order || order.checkout_session_id !== session.id ||\n      order.amount_cents !== session.amount_total || order.currency !== session.currency ||\n      ![true, false, 0, 1].includes(order.livemode) || Boolean(order.livemode) !== session.livemode || order.stripe_account_id !== account) {\n    return new Response('payment mismatch', { status: 409 });\n  }\n  const where = {\n    id: order.id, checkout_session_id: session.id, status: 'pending',\n    amount_cents: order.amount_cents, currency: order.currency,\n    livemode: order.livemode, stripe_account_id: account,\n  };\n  const updated = await sw.db.update('payment_requests', {\n    set: { status: 'paid', paid_event_id: event.id, paid_at: new Date().toISOString() }, where,\n  });\n  if (updated.data.length === 1 && updated.data[0].id === order.id) return Response.json({ ok: true, transitioned: true });\n  const current = (await sw.db.from('payment_requests', { where: { id: order.id }, limit: 1 })).data[0];\n  if (current?.status === 'paid' && current.paid_event_id === event.id &&\n      current.checkout_session_id === session.id && current.amount_cents === order.amount_cents &&\n      current.currency === order.currency && current.livemode === order.livemode &&\n      current.stripe_account_id === account) return Response.json({ ok: true, transitioned: false });\n  return new Response('payment state unresolved', { status: 409 });\n}\n```";
export const RECIPE_MAGIC_LINK_BROWSER = "```ts\n// api/auth/magic.ts\nexport default async function (req, sw) {\n  if (req.method !== 'POST') return new Response('method not allowed', { status: 405 });\n  const body = await req.json().catch(() => null);\n  if (!body || typeof body.token !== 'string' || !body.token) {\n    return new Response('request a new sign-in link', { status: 400 });\n  }\n  try {\n    const session = await sw.auth.verifyOtp({ token: body.token });\n    if (session.mfa_required) return Response.json({ mfa_required: true, mfa_token: session.mfa_token }, { headers: { 'Cache-Control': 'no-store' } });\n    sw.auth.setSessionCookies(session.token, session.refresh_token);\n    const destination = new URL(session.redirect_uri ?? '/', req.url);\n    // This example intentionally navigates only within the app.\n    const redirect = destination.origin === new URL(req.url).origin &&\n      destination.pathname !== '/auth/magic' ? destination.pathname + destination.search + destination.hash : '/';\n    return Response.json({ redirect });\n  } catch {\n    return new Response('request a new sign-in link', { status: 400 });\n  }\n}\n```\n\n```ts\n// src/auth/magic.ts\n// Run once when the browser renders /auth/magic; do not call from a retried effect.\nexport async function completeMagicLink() {\n  const token = new URLSearchParams(location.search).get('token');\n  history.replaceState(null, '', '/auth/magic');\n  if (!token) return 'Request a new sign-in link.';\n  try {\n    const response = await fetch('/api/auth/magic', {\n      method: 'POST', credentials: 'include',\n      headers: { 'content-type': 'application/json' }, body: JSON.stringify({ token }),\n    });\n    if (!response.ok) return 'Request a new sign-in link.';\n    const answer = await response.json();\n    if (answer.mfa_required) return 'Sign-in needs an authenticator or backup code. This page cannot complete that step.';\n    const { redirect } = answer;\n    const destination = new URL(redirect, location.origin);\n    location.assign(destination.origin === location.origin && destination.pathname !== '/auth/magic'\n      ? destination.href : '/');\n  } catch {\n    return 'Request a new sign-in link.';\n  }\n}\n```";
export const RECIPE_AI_RECEIPTS = "### Schema: private uploads and saved receipts\n\n```ts\n// db/schema.ts\nimport { files, id, json, number, owner, schema, table, text } from 'somewhere/db';\n\n// receipts: each signed-in user sees and writes only their own saved receipts\n// through the generated somewhere:data client. The browser creates a row only\n// after the user reviews the extracted values and presses Save. One receipt\n// per uploaded file per user: user_id is the owner column owner() manages, so\n// a second save of the same file is refused (DATA_CONFLICT) instead of\n// creating a duplicate, and one user's file ids reveal nothing to another.\n//\n// receipt_files: private uploads, readable only by the uploader. The types are\n// exactly the image and PDF formats the model accepts; 5MB (5 MiB) keeps the\n// base64-encoded request well inside the platform's attachment request limit.\nexport default schema({\n  receipts: table(\n    {\n      id: id(),\n      file_id: text(),\n      merchant: text(),\n      purchased_on: text({ default: '' }),\n      currency: text({ default: '' }),\n      total: number({ nullable: true }),\n      lines: json(),\n    },\n    {\n      scope: owner(),\n      unique: [['user_id', 'file_id']],\n      client: {\n        read: ['id', 'file_id', 'merchant', 'purchased_on', 'currency', 'total', 'lines'],\n        create: ['file_id', 'merchant', 'purchased_on', 'currency', 'total', 'lines'],\n        delete: true,\n        identity: 'authenticated',\n      },\n    },\n  ),\n}, {\n  files: {\n    receipt_files: files({\n      path: '/receipts',\n      scope: owner(),\n      client: { read: true, upload: true, delete: true },\n      limits: { maxSize: '5MB', types: ['image/jpeg', 'image/png', 'image/gif', 'image/webp', 'application/pdf'] },\n    }),\n  },\n});\n```\n\n### Shared types\n\n```ts\n// types/receipts.ts\n// Type aliases, not interfaces: a line list is stored in a json() column, and\n// only a type alias is assignable to the generated client's JSON value type.\nexport type ReceiptLine = { description: string; amount: number };\n\n/** What extraction proposes and the user edits. Nothing is saved until Save. */\nexport type ReceiptDraft = {\n  file_id: string;\n  merchant: string;\n  /** YYYY-MM-DD, or '' when the receipt shows no date. */\n  purchased_on: string;\n  /** ISO 4217 code such as 'USD', or '' when the receipt shows none. */\n  currency: string;\n  lines: ReceiptLine[];\n  total: number | null;\n};\n\nexport type ReceiptDraftErrors = Partial<Record<'merchant' | 'purchased_on' | 'currency' | 'lines' | 'total', string>>;\n\n/** The extraction function's answer. `retry` tells the page whether trying the\n *  same file again is reasonable; the page never retries on its own. */\nexport type ExtractAnswer =\n  | { ok: true; draft: ReceiptDraft }\n  | { ok: false; error: { code: string; message: string; retry: boolean } };\n\n/** A save either committed, was refused (nothing written), or its outcome is\n *  unknown because the response was lost. Unknown is never reported as unsaved. */\nexport type SaveOutcome =\n  | { kind: 'saved'; message: string }\n  | { kind: 'refused'; message: string }\n  | { kind: 'unknown'; message: string };\n\n/** A read-only look for this file's saved receipt. */\nexport type SavedCheck = { kind: 'found'; message: string } | { kind: 'not-found' } | { kind: 'unknown'; message: string };\n\nexport type ReceiptFlowStep =\n  | { kind: 'choose' }\n  | { kind: 'uploading' }\n  | { kind: 'extracting'; fileId: string }\n  | { kind: 'review'; draft: ReceiptDraft }\n  | { kind: 'saving'; draft: ReceiptDraft }\n  /** The save's outcome is unknown. `checked`: a look found nothing yet. */\n  | { kind: 'unconfirmed'; draft: ReceiptDraft; checked: boolean }\n  | { kind: 'saved'; message: string };\n```\n\n### Server helpers: model, response schema and answer checks\n\n```ts\n// api/_lib/receipt-extraction.ts\nimport type { ExtractAnswer, ReceiptDraft, ReceiptLine } from '../../types/receipts';\n\n// An Anthropic completion model from ai_catalog (feature 'complete', provider\n// 'anthropic'). Images and PDFs reach the model only on provider 'anthropic',\n// and this model accepts response_schema (claude-opus-5-5 does not).\nexport const RECEIPT_MODEL = 'claude-sonnet-4-6';\n/** This example's own per-user limit on metered readings (not a platform quota). */\nexport const RECEIPT_READS_PER_HOUR = 20;\n/** db/schema.ts receipt_files maxSize: '5MB' is 5 MiB. */\nexport const RECEIPT_MAX_BYTES = 5 * 1024 * 1024;\nconst MAX_LINES = 100;\nconst MAX_TEXT = 200;\n\n/** The structured answer the model must return; validated again below. */\nexport const RECEIPT_SCHEMA = {\n  type: 'object',\n  additionalProperties: false,\n  required: ['merchant', 'purchased_on', 'currency', 'lines', 'total'],\n  properties: {\n    merchant: { type: 'string', description: 'Store or business name as printed.' },\n    purchased_on: { type: 'string', description: 'Purchase date as YYYY-MM-DD, or an empty string if none is shown.' },\n    currency: { type: 'string', description: 'ISO 4217 code such as USD, or an empty string if unclear.' },\n    lines: {\n      type: 'array',\n      items: {\n        type: 'object',\n        additionalProperties: false,\n        required: ['description', 'amount'],\n        properties: { description: { type: 'string' }, amount: { type: 'number' } },\n      },\n    },\n    total: { type: ['number', 'null'], description: 'Total paid, or null if not shown.' },\n  },\n} as const;\n\nexport const RECEIPT_PROMPT = 'Read this receipt. Return each purchased item with its price, the merchant, '\n  + 'the purchase date and the total. Copy values as printed; do not invent missing ones.';\n\n/** A collection file id is one path segment; anything else is refused. */\nexport function isFileId(value: unknown): value is string {\n  return typeof value === 'string' && value.length > 0 && value.length <= 128\n    && !value.includes('/') && value !== '.' && value !== '..';\n}\n\nconst IMAGE_TYPES = ['image/jpeg', 'image/png', 'image/gif', 'image/webp'] as const;\ntype ImageType = (typeof IMAGE_TYPES)[number];\n\n/** The native input block for an uploaded file, or null for any other type. */\nexport function inputBlock(contentType: string | null, bytes: Uint8Array): SomewhereAiImageInputBlock | SomewhereAiDocumentInputBlock | null {\n  const data = toBase64(bytes);\n  if (contentType === 'application/pdf') {\n    return { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data } };\n  }\n  if (IMAGE_TYPES.includes(contentType as ImageType)) {\n    return { type: 'image', source: { type: 'base64', media_type: contentType as ImageType, data } };\n  }\n  return null;\n}\n\n/** Plain base64 (no data: prefix), encoded in chunks to stay within argument limits. */\nexport function toBase64(bytes: Uint8Array): string {\n  let binary = '';\n  for (let i = 0; i < bytes.length; i += 0x8000) {\n    binary += String.fromCharCode(...bytes.subarray(i, i + 0x8000));\n  }\n  return btoa(binary);\n}\n\nfunction text(value: unknown, max = MAX_TEXT): string | null {\n  return typeof value === 'string' ? value.trim().slice(0, max) : null;\n}\n\nfunction money(value: unknown): number | null {\n  return typeof value === 'number' && Number.isFinite(value) ? Math.round(value * 100) / 100 : null;\n}\n\n/** The model's structured answer as a draft, or null when it is not one. */\nexport function draftFromModel(parsed: unknown, fileId: string): ReceiptDraft | null {\n  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return null;\n  const answer = parsed as Record<string, unknown>;\n  const merchant = text(answer.merchant);\n  const purchasedOn = text(answer.purchased_on, 10);\n  const currency = text(answer.currency, 3);\n  if (merchant === null || purchasedOn === null || currency === null || !Array.isArray(answer.lines)) return null;\n  const lines: ReceiptLine[] = [];\n  for (const raw of answer.lines.slice(0, MAX_LINES)) {\n    const line = raw && typeof raw === 'object' ? raw as Record<string, unknown> : {};\n    const description = text(line.description);\n    const amount = money(line.amount);\n    if (description === null || amount === null) return null;\n    lines.push({ description, amount });\n  }\n  const total = answer.total === null ? null : money(answer.total);\n  if (total === null && answer.total !== null) return null;\n  return {\n    file_id: fileId,\n    merchant,\n    purchased_on: /^\\d{4}-\\d{2}-\\d{2}$/.test(purchasedOn) ? purchasedOn : '',\n    currency: /^[A-Za-z]{3}$/.test(currency) ? currency.toUpperCase() : '',\n    lines,\n    total,\n  };\n}\n\nexport function refusal(status: number, code: string, message: string, retry: boolean): Response {\n  const body: ExtractAnswer = { ok: false, error: { code, message, retry } };\n  return Response.json(body, { status });\n}\n\n/**\n * A failed model call, in words the page can show. Messages say what the\n * user can do next and make no claim about charges; only a rate limit is\n * offered as worth trying again later.\n */\nexport function modelFailure(reason: unknown): Response {\n  const code = reason && typeof reason === 'object' && typeof (reason as { code?: unknown }).code === 'string'\n    ? (reason as { code: string }).code : '';\n  switch (code) {\n    case 'INSUFFICIENT_BALANCE':\n    case 'PAID_API_NOT_ACTIVATED':\n    case 'PAID_AI_DISABLED':\n      return refusal(402, code, 'Receipt reading is unavailable right now. Enter the values yourself.', false);\n    case 'AI_SPEND_CAP_REACHED':\n      return refusal(429, code, 'Receipt reading is paused for now. Enter the values yourself.', false);\n    case 'AI_INPUT_UNSUPPORTED':\n    case 'AI_INPUT_TOO_LARGE':\n      return refusal(400, code, 'This file could not be read. Upload a JPEG, PNG, GIF, WebP or PDF under 5 MB.', false);\n    case 'RATE_LIMITED':\n      return refusal(429, code, 'Too many receipts at once. Try again in a minute.', true);\n    default:\n      return refusal(502, 'EXTRACTION_FAILED',\n        'Reading the receipt did not finish. It was not retried automatically, because it may already have been charged. '\n        + 'Enter the values yourself, or try again once.', false);\n  }\n}\n```\n\n### The extraction function\n\n```ts\n// api/receipts/extract.ts\n// POST /api/receipts/extract  { file_id }  →  { ok: true, draft } | { ok: false, error }\n//\n// Reads one of the signed-in user's own receipt uploads, makes one sw.ai.chat\n// request for structured rows (the platform may add one separately billed\n// structured-output repair inside it), and returns them as an unsaved draft.\n// Saving happens later, in the browser, only after the user reviews the values.\nimport type { ExtractAnswer } from '../../types/receipts';\nimport {\n  draftFromModel, inputBlock, isFileId, modelFailure, RECEIPT_MAX_BYTES, RECEIPT_MODEL,\n  RECEIPT_PROMPT, RECEIPT_READS_PER_HOUR, RECEIPT_SCHEMA, refusal,\n} from '../_lib/receipt-extraction';\n\nexport default async (req: Request, sw: SomewhereRuntimeContext): Promise<Response> => {\n  if (req.method !== 'POST') return new Response('Method not allowed', { status: 405, headers: { Allow: 'POST' } });\n  // Required first: sw.fs below acts as this verified user. Without a signed-in\n  // user it would act with project authority over every file.\n  const user = await sw.auth.requireUser(req);\n\n  const body: unknown = await req.json().catch(() => null);\n  const fileId = body && typeof body === 'object' ? (body as { file_id?: unknown }).file_id : undefined;\n  if (!isFileId(fileId)) return refusal(400, 'VALIDATION_ERROR', 'Choose a receipt to read.', false);\n\n  // Each reading is metered, so this example allows each user 20 per hour,\n  // counted before any file read or model request.\n  const limit = await sw.rateLimit.check(`receipt-extract:${user.id}`, RECEIPT_READS_PER_HOUR, 3600);\n  if (!limit.allowed) {\n    return refusal(429, 'RECEIPT_RATE_LIMITED', `You can read ${RECEIPT_READS_PER_HOUR} receipts an hour. Try again later, or enter the values yourself.`, false);\n  }\n\n  const file = await findOwnedReceipt(sw, fileId);\n  if (!file) return refusal(404, 'RECEIPT_NOT_FOUND', 'That receipt was not found. Upload it again.', false);\n  if (file.size_bytes > RECEIPT_MAX_BYTES) return refusal(413, 'RECEIPT_TOO_LARGE', 'Receipts must be under 5 MB.', false);\n\n  const bytes = new Uint8Array(await (await sw.fs.read(file.path)).arrayBuffer());\n  const block = inputBlock(file.content_type, bytes);\n  if (!block) return refusal(415, 'RECEIPT_TYPE_UNSUPPORTED', 'Upload a JPEG, PNG, GIF, WebP or PDF.', false);\n\n  let result: SomewhereAiChatResult;\n  try {\n    // No conversation_id: this is a one-shot extraction. A failed call is\n    // never repeated here.\n    result = await sw.ai.chat({\n      provider: 'anthropic',\n      model: RECEIPT_MODEL,\n      max_tokens: 2048,\n      response_schema: RECEIPT_SCHEMA,\n      messages: [{ role: 'user', content: [block, { type: 'text', text: RECEIPT_PROMPT }] }],\n      stream: false,\n    });\n  } catch (reason: unknown) {\n    return modelFailure(reason);\n  }\n\n  const draft = draftFromModel(result.parsed, fileId);\n  if (!draft) {\n    return refusal(422, 'RECEIPT_UNREADABLE', 'No rows could be read from this receipt. Enter them yourself, or upload a clearer image.', false);\n  }\n  const answer: ExtractAnswer = { ok: true, draft };\n  return Response.json(answer);\n};\n\n/** The one file stored under this upload's id, if the signed-in user owns it.\n *  Listing as that user shows only their own files, so another user's id\n *  answers exactly like a missing one. */\nasync function findOwnedReceipt(sw: SomewhereRuntimeContext, fileId: string): Promise<SomewhereFsListEntry | null> {\n  let listing: SomewhereFsListResult;\n  try {\n    listing = await sw.fs.list(`/receipts/${fileId}/`);\n  } catch (reason: unknown) {\n    const status = reason && typeof reason === 'object' ? (reason as { status?: unknown }).status : undefined;\n    if (status === 403 || status === 404) return null;\n    throw reason;\n  }\n  const found = listing.entries.filter((entry) => entry.type === 'file');\n  return found.length === 1 ? found[0] : null;\n}\n```\n\n### Browser services: upload, read, save and check\n\n```ts\n// src/services/receipts.ts\nimport { data, DataError } from 'somewhere:data';\nimport { files } from 'somewhere:files';\nimport type { ExtractAnswer, ReceiptDraft, ReceiptDraftErrors, SavedCheck, SaveOutcome } from '../../types/receipts';\n\n// Mirrors db/schema.ts receipt_files; the platform enforces the same limits.\nexport const RECEIPT_TYPES = ['image/jpeg', 'image/png', 'image/gif', 'image/webp', 'application/pdf'] as const;\nexport const RECEIPT_MAX_BYTES = 5 * 1024 * 1024;\n\nexport type Outcome<T> = { ok: true; value: T } | { ok: false; message: string; retry: boolean };\n\n/** Checked here for a fast answer; the collection's limits are the authority. */\nexport function checkReceiptFile(file: File): string | null {\n  if (!RECEIPT_TYPES.includes(file.type as (typeof RECEIPT_TYPES)[number])) return 'Choose a JPEG, PNG, GIF, WebP or PDF.';\n  if (file.size > RECEIPT_MAX_BYTES) return 'Receipts must be under 5 MB.';\n  return null;\n}\n\n/** Private upload into the signed-in user's receipt_files collection. */\nexport async function uploadReceipt(file: File): Promise<Outcome<string>> {\n  const problem = checkReceiptFile(file);\n  if (problem) return { ok: false, message: problem, retry: false };\n  const result = await files.receipt_files.upload(file);\n  if (result.error) {\n    if (result.error.code === 'PAYLOAD_TOO_LARGE') return { ok: false, message: 'Receipts must be under 5 MB.', retry: false };\n    if (result.error.code === 'FILE_TYPE_NOT_ALLOWED') return { ok: false, message: 'Choose a JPEG, PNG, GIF, WebP or PDF.', retry: false };\n    if (result.error.code === 'AUTH_REQUIRED') return { ok: false, message: 'Your session ended. Sign in again.', retry: false };\n    return { ok: false, message: result.error.message || 'The upload failed. Try again.', retry: true };\n  }\n  return { ok: true, value: result.data.id };\n}\n\n/** One extraction request. The caller decides whether to ask again. */\nexport async function extractReceipt(fileId: string): Promise<Outcome<ReceiptDraft>> {\n  let response: Response;\n  try {\n    response = await fetch('/api/receipts/extract', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ file_id: fileId }),\n    });\n  } catch {\n    // The request may or may not have reached the server, so this is not\n    // presented as safe to repeat.\n    return { ok: false, message: 'Could not confirm the receipt was read. Check your connection, then enter the values or try once more.', retry: false };\n  }\n  if (response.status === 401) return { ok: false, message: 'Your session ended. Sign in again.', retry: false };\n  const answer = await response.json().catch(() => null) as ExtractAnswer | null;\n  if (!answer) return { ok: false, message: 'The receipt could not be read. Enter the values yourself.', retry: false };\n  if (!answer.ok) return { ok: false, message: answer.error.message, retry: answer.error.retry };\n  return { ok: true, value: answer.draft };\n}\n\nexport function validateDraft(draft: ReceiptDraft): ReceiptDraftErrors {\n  const errors: ReceiptDraftErrors = {};\n  if (!draft.merchant.trim()) errors.merchant = 'Add the merchant.';\n  if (draft.purchased_on && !/^\\d{4}-\\d{2}-\\d{2}$/.test(draft.purchased_on)) errors.purchased_on = 'Use YYYY-MM-DD, or leave it empty.';\n  if (draft.currency && !/^[A-Z]{3}$/.test(draft.currency)) errors.currency = 'Use a three-letter code such as USD, or leave it empty.';\n  if (draft.lines.some((line) => !line.description.trim() || !Number.isFinite(line.amount))) errors.lines = 'Every line needs a description and an amount.';\n  if (draft.total !== null && !Number.isFinite(draft.total)) errors.total = 'Enter the total as a number, or leave it empty.';\n  return errors;\n}\n\n/** Refusals the platform answers before writing anything. */\nconst NOT_WRITTEN = new Set([\n  'AUTH_REQUIRED', 'DATA_ACCESS_DENIED', 'DATA_CONTRACT_MISMATCH', 'DATA_IDENTITY_MISMATCH',\n  'DATA_INPUT_INVALID', 'DATA_INPUT_TOO_LARGE', 'DATA_OPERATION_INVALID', 'DATA_VALUE_INVALID',\n]);\n\nfunction refusedMessage(code: string): string {\n  if (code === 'AUTH_REQUIRED') return 'Your session ended. Sign in again, then save.';\n  if (code === 'DATA_CONTRACT_MISMATCH') return 'This app was just updated. Reload the page, then save.';\n  return 'The receipt was not saved. Check the values and save again.';\n}\n\n/** Saves the reviewed values once and never repeats the write. A lost\n *  response is reported as unknown, not as unsaved. Never calls the model. */\nexport async function saveReceipt(draft: ReceiptDraft): Promise<SaveOutcome> {\n  try {\n    const result = await data.receipts.create({\n      file_id: draft.file_id,\n      merchant: draft.merchant.trim(),\n      purchased_on: draft.purchased_on,\n      currency: draft.currency,\n      total: draft.total,\n      lines: draft.lines.map((line) => ({ description: line.description.trim(), amount: line.amount })),\n    });\n    return { kind: 'saved', message: result.data ? `Saved the receipt from ${result.data.merchant}.` : 'Saved the receipt.' };\n  } catch (reason: unknown) {\n    const code = reason instanceof DataError ? reason.code : null;\n    // One receipt per file (db/schema.ts unique): this file's receipt exists.\n    if (code === 'DATA_CONFLICT') return { kind: 'saved', message: 'This receipt is already saved.' };\n    if (code && NOT_WRITTEN.has(code)) return { kind: 'refused', message: refusedMessage(code) };\n  }\n  return { kind: 'unknown', message: 'We could not confirm the save. Check for the saved receipt before saving again.' };\n}\n\n/** Read-only: is this file's receipt among the user's saved receipts? */\nexport async function findSavedReceipt(fileId: string): Promise<SavedCheck> {\n  try {\n    const page = await data.receipts.list({ where: { file_id: fileId }, limit: 1 });\n    const saved = page.data[0];\n    return saved ? { kind: 'found', message: `Saved the receipt from ${saved.merchant}.` } : { kind: 'not-found' };\n  } catch {\n    return { kind: 'unknown', message: 'Could not check right now. Try again in a moment.' };\n  }\n}\n```\n\n### The page flow\n\n```ts\n// src/data/useReceiptFlow.ts\nimport { useEffect, useRef, useState } from 'react';\nimport type { ReceiptDraft, ReceiptDraftErrors, ReceiptFlowStep } from '../../types/receipts';\nimport { extractReceipt, findSavedReceipt, saveReceipt, uploadReceipt, validateDraft } from '../services/receipts';\n\nexport interface ReceiptFlow {\n  step: ReceiptFlowStep;\n  /** The last failure, with whether trying the same action again is reasonable. */\n  problem: { message: string; retry: boolean } | null;\n  errors: ReceiptDraftErrors;\n  /** The uploaded file whose reading can be requested again by the user. */\n  retryFileId: string | null;\n  choose(file: File): Promise<void>;\n  extract(fileId: string): Promise<void>;\n  enterManually(): void;\n  edit(draft: ReceiptDraft): void;\n  save(): Promise<void>;\n  /** After an unconfirmed save: look for this file's saved receipt (read-only). */\n  checkSaved(): Promise<void>;\n  startOver(): void;\n}\n\nconst BLANK = (fileId: string): ReceiptDraft => ({ file_id: fileId, merchant: '', purchased_on: '', currency: '', lines: [], total: null });\n\n// Upload → one extraction → review → explicit save. Editing and saving never\n// call the model; a failed reading is only repeated if the user asks.\nexport function useReceiptFlow(): ReceiptFlow {\n  const mounted = useRef(false);\n  // Set synchronously, so a second click before React re-renders cannot start\n  // a second upload, model call or save.\n  const busy = useRef(false);\n  const [step, setStep] = useState<ReceiptFlowStep>({ kind: 'choose' });\n  const [problem, setProblem] = useState<ReceiptFlow['problem']>(null);\n  const [retryFileId, setRetryFileId] = useState<string | null>(null);\n\n  useEffect(() => {\n    mounted.current = true;\n    return () => { mounted.current = false; };\n  }, []);\n\n  async function once(action: () => Promise<void>): Promise<void> {\n    if (busy.current) return;\n    busy.current = true;\n    try {\n      await action();\n    } finally {\n      busy.current = false;\n    }\n  }\n\n  async function runExtraction(fileId: string) {\n    setProblem(null);\n    setStep({ kind: 'extracting', fileId });\n    const read = await extractReceipt(fileId);\n    if (!mounted.current) return;\n    if (read.ok) {\n      setRetryFileId(null);\n      setStep({ kind: 'review', draft: read.value });\n    } else {\n      setProblem({ message: read.message, retry: read.retry });\n      setRetryFileId(fileId);\n      setStep({ kind: 'choose' });\n    }\n  }\n\n  const draft = step.kind === 'review' || step.kind === 'saving' || step.kind === 'unconfirmed' ? step.draft : null;\n  const errors = draft ? validateDraft(draft) : {};\n\n  return {\n    step,\n    problem,\n    errors,\n    retryFileId,\n    choose: (file) => once(async () => {\n      setProblem(null);\n      setRetryFileId(null);\n      setStep({ kind: 'uploading' });\n      const uploaded = await uploadReceipt(file);\n      if (!mounted.current) return;\n      if (!uploaded.ok) {\n        setProblem({ message: uploaded.message, retry: uploaded.retry });\n        setStep({ kind: 'choose' });\n        return;\n      }\n      await runExtraction(uploaded.value);\n    }),\n    extract: (fileId) => once(() => runExtraction(fileId)),\n    enterManually() {\n      if (!retryFileId || busy.current) return;\n      setProblem(null);\n      setStep({ kind: 'review', draft: BLANK(retryFileId) });\n      setRetryFileId(null);\n    },\n    edit(next) {\n      if (step.kind === 'review') setStep({ kind: 'review', draft: next });\n    },\n    // From review, or again from an unconfirmed save after a look found\n    // nothing: a second write of the same file is refused, never duplicated.\n    save: () => once(async () => {\n      const ready = step.kind === 'review' || (step.kind === 'unconfirmed' && step.checked);\n      if (!ready || Object.keys(errors).length > 0) return;\n      const reviewed = step.draft;\n      setProblem(null);\n      setStep({ kind: 'saving', draft: reviewed });\n      const saved = await saveReceipt(reviewed);\n      if (!mounted.current) return;\n      if (saved.kind === 'saved') setStep({ kind: 'saved', message: saved.message });\n      else if (saved.kind === 'refused') {\n        setProblem({ message: saved.message, retry: true });\n        setStep({ kind: 'review', draft: reviewed });\n      } else {\n        setProblem({ message: saved.message, retry: false });\n        setStep({ kind: 'unconfirmed', draft: reviewed, checked: false });\n      }\n    }),\n    checkSaved: () => once(async () => {\n      if (step.kind !== 'unconfirmed') return;\n      const pending = step.draft;\n      const found = await findSavedReceipt(pending.file_id);\n      if (!mounted.current) return;\n      if (found.kind === 'found') {\n        setProblem(null);\n        setStep({ kind: 'saved', message: found.message });\n      } else if (found.kind === 'not-found') {\n        // Absence is not proof the save failed; say what is known.\n        setProblem({ message: 'No saved receipt for this file yet. If you just saved, check again in a moment. Saving again is safe: a duplicate is refused.', retry: true });\n        setStep({ kind: 'unconfirmed', draft: pending, checked: true });\n      } else {\n        setProblem({ message: found.message, retry: true });\n      }\n    }),\n    startOver() {\n      if (busy.current) return;\n      setProblem(null);\n      setRetryFileId(null);\n      setStep({ kind: 'choose' });\n    },\n  };\n}\n```\n\n### The review form\n\n```tsx\n// src/ui/ReceiptReview.tsx\nimport type { ChangeEvent, FormEvent } from 'react';\nimport type { ReceiptDraft, ReceiptLine } from '../../types/receipts';\nimport type { ReceiptFlow } from '../data/useReceiptFlow';\nimport { RECEIPT_TYPES } from '../services/receipts';\n\n/** An empty field is NaN, which validation reports, never a silent 0. */\nconst amountOf = (value: string): number => (value.trim() === '' ? Number.NaN : Number(value));\n\nexport function ReceiptReview({ flow }: { flow: ReceiptFlow }) {\n  const { step, problem } = flow;\n  return (\n    <div className=\"panel\">\n      <h1 className=\"panel__title\">Receipts</h1>\n      {step.kind === 'choose' ? <ChooseFile flow={flow} /> : null}\n      {step.kind === 'uploading' ? <p role=\"status\">Uploading…</p> : null}\n      {step.kind === 'extracting' ? <p role=\"status\">Reading the receipt…</p> : null}\n      {step.kind === 'review' || step.kind === 'saving' ? <ReviewForm flow={flow} draft={step.draft} saving={step.kind === 'saving'} /> : null}\n      {step.kind === 'unconfirmed' ? (\n        <div className=\"actions\">\n          <p role=\"status\">Saving {step.draft.merchant || 'this receipt'} was not confirmed.</p>\n          <button type=\"button\" className=\"button\" onClick={() => void flow.checkSaved()}>Check saved receipt</button>\n          {step.checked ? <button type=\"button\" className=\"button button--quiet\" onClick={() => void flow.save()}>Save again</button> : null}\n        </div>\n      ) : null}\n      {step.kind === 'saved' ? (\n        <div className=\"actions\">\n          <p role=\"status\">{step.message}</p>\n          <button type=\"button\" className=\"button\" onClick={flow.startOver}>Add another receipt</button>\n        </div>\n      ) : null}\n      {problem ? <p className=\"notice error\" role=\"alert\">{problem.message}</p> : null}\n    </div>\n  );\n}\n\nfunction ChooseFile({ flow }: { flow: ReceiptFlow }) {\n  function onChange(event: ChangeEvent<HTMLInputElement>) {\n    const file = event.target.files?.[0];\n    event.target.value = '';\n    if (file) void flow.choose(file);\n  }\n  const fileId = flow.retryFileId;\n  return (\n    <>\n      <div className=\"field\">\n        <label htmlFor=\"receipt-file\">Receipt photo or PDF <span className=\"hint\">up to 5 MB</span></label>\n        <input id=\"receipt-file\" type=\"file\" accept={RECEIPT_TYPES.join(',')} onChange={onChange} />\n      </div>\n      {fileId ? (\n        <div className=\"actions\">\n          <button type=\"button\" className=\"button button--quiet\" onClick={flow.enterManually}>Enter the values myself</button>\n          {flow.problem?.retry ? <button type=\"button\" className=\"button\" onClick={() => void flow.extract(fileId)}>Read it again</button> : null}\n        </div>\n      ) : null}\n    </>\n  );\n}\n\nfunction ReviewForm({ flow, draft, saving }: { flow: ReceiptFlow; draft: ReceiptDraft; saving: boolean }) {\n  const { errors } = flow;\n  const set = (patch: Partial<ReceiptDraft>) => flow.edit({ ...draft, ...patch });\n  const setLine = (index: number, patch: Partial<ReceiptLine>) =>\n    set({ lines: draft.lines.map((line, i) => (i === index ? { ...line, ...patch } : line)) });\n\n  function onSubmit(event: FormEvent<HTMLFormElement>) {\n    event.preventDefault();\n    void flow.save();\n  }\n\n  return (\n    <form onSubmit={onSubmit} noValidate>\n      <p className=\"muted\">Check every value. Nothing is saved until you press Save.</p>\n      <div className=\"field\">\n        <label htmlFor=\"receipt-merchant\">Merchant</label>\n        <input id=\"receipt-merchant\" value={draft.merchant} disabled={saving} onChange={(e) => set({ merchant: e.target.value })} />\n        {errors.merchant ? <p className=\"error\">{errors.merchant}</p> : null}\n      </div>\n      <div className=\"field\">\n        <label htmlFor=\"receipt-date\">Date <span className=\"hint\">YYYY-MM-DD</span></label>\n        <input id=\"receipt-date\" value={draft.purchased_on} disabled={saving} onChange={(e) => set({ purchased_on: e.target.value.trim() })} />\n        {errors.purchased_on ? <p className=\"error\">{errors.purchased_on}</p> : null}\n      </div>\n      <div className=\"field\">\n        <label htmlFor=\"receipt-currency\">Currency</label>\n        <input id=\"receipt-currency\" value={draft.currency} disabled={saving} onChange={(e) => set({ currency: e.target.value.trim().toUpperCase() })} />\n        {errors.currency ? <p className=\"error\">{errors.currency}</p> : null}\n      </div>\n      <fieldset className=\"field\" disabled={saving}>\n        <legend>Items</legend>\n        {draft.lines.map((line, index) => (\n          <div className=\"actions\" key={index}>\n            <input aria-label={`Item ${index + 1}`} value={line.description} onChange={(e) => setLine(index, { description: e.target.value })} />\n            <input aria-label={`Amount ${index + 1}`} type=\"number\" step=\"0.01\" value={Number.isNaN(line.amount) ? '' : line.amount}\n              onChange={(e) => setLine(index, { amount: amountOf(e.target.value) })} />\n            <button type=\"button\" className=\"link-button link-button--danger\" onClick={() => set({ lines: draft.lines.filter((_, i) => i !== index) })}>Remove</button>\n          </div>\n        ))}\n        <button type=\"button\" className=\"link-button\" onClick={() => set({ lines: [...draft.lines, { description: '', amount: Number.NaN }] })}>Add item</button>\n        {errors.lines ? <p className=\"error\">{errors.lines}</p> : null}\n      </fieldset>\n      <div className=\"field\">\n        <label htmlFor=\"receipt-total\">Total</label>\n        <input id=\"receipt-total\" type=\"number\" step=\"0.01\" disabled={saving} value={draft.total === null || Number.isNaN(draft.total) ? '' : draft.total}\n          onChange={(e) => set({ total: e.target.value.trim() === '' ? null : amountOf(e.target.value) })} />\n        {errors.total ? <p className=\"error\">{errors.total}</p> : null}\n      </div>\n      <div className=\"actions\">\n        <button type=\"submit\" className=\"button\" disabled={saving || Object.keys(errors).length > 0} aria-busy={saving}>{saving ? 'Saving…' : 'Save'}</button>\n        <button type=\"button\" className=\"button button--quiet\" disabled={saving} onClick={flow.startOver}>Discard</button>\n      </div>\n    </form>\n  );\n}\n```\n\n### The home page\n\n```tsx\n// src/pages/HomePage.tsx\nimport type { User } from '../../types/auth';\nimport { useReceiptFlow } from '../data/useReceiptFlow';\nimport { ReceiptReview } from '../ui/ReceiptReview';\nimport { SignedInLayout } from './SignedInLayout';\n\n// Replaces the starter's home page. App.tsx already renders this only for a\n// signed-in user, keyed by user id, so another account starts a fresh flow.\nexport function HomePage({ user }: { user: User }) {\n  const flow = useReceiptFlow();\n  return (\n    <SignedInLayout user={user}>\n      <ReceiptReview flow={flow} />\n    </SignedInLayout>\n  );\n}\n```";
